'use strict';
// Version 2.6: everyday dilemmas and philosopher cards (English). Same structure and ids as denken.js (see the notes there).
// Only the file for the chosen language is loaded.

const DENKEN_EN = {
  people: {
    kant: { name: 'Immanuel Kant', years: '1724–1804', looks: 'looks to firm principles', idea: 'Act only on a rule that could hold for everyone, and never treat people merely as a means.', wiki: 'Immanuel Kant' },
    mill: { name: 'John Stuart Mill', years: '1806–1873', looks: 'looks to the outcome', idea: 'What is right is whatever brings the most happiness and the least suffering overall. Everyone counts equally.', wiki: 'John Stuart Mill' },
    aristoteles: { name: 'Aristotle', years: '384–322 BC', looks: 'looks to character', idea: 'A good life comes from building good character and finding the right measure in every situation.', wiki: 'Aristotle' },
    nietzsche: { name: 'Friedrich Nietzsche', years: '1844–1900', looks: 'questions morality itself', idea: 'Ask where our morality comes from and whom it serves, and become who you are.', wiki: 'Friedrich Nietzsche' },
    arendt: { name: 'Hannah Arendt', years: '1906–1975', looks: 'thinks about acting together', idea: 'People act together. Promising and forgiving are what make that possible.', wiki: 'Hannah Arendt' },
    beauvoir: { name: 'Simone de Beauvoir', years: '1908–1986', looks: 'thinks about freedom', idea: 'We are free and must answer for our choices. My freedom depends on the freedom of others.', wiki: 'Simone de Beauvoir' },
    konfuzius: { name: 'Confucius', years: '551–479 BC (traditional dates)', looks: 'looks to relationships', idea: 'Humaneness begins in the family and grows outward through respect and practice.', wiki: 'Confucius' },
    singer: { name: 'Peter Singer', years: 'born 1946', looks: 'looks to everyone’s suffering', idea: 'Equal suffering counts equally, no matter whose it is or how far away.', wiki: 'Peter Singer' },
    schopenhauer: { name: 'Arthur Schopenhauer', years: '1788–1860', looks: 'builds on compassion', idea: 'Compassion is the root of all genuine morality.', wiki: 'Arthur Schopenhauer' },
    epikur: { name: 'Epicurus', years: '341–270 BC', looks: 'seeks calm joy', idea: 'Happiness is calm joy: little pain, no fear, good friends.', wiki: 'Epicurus' },
    hume: { name: 'David Hume', years: '1711–1776', looks: 'trusts feeling', idea: 'Not reason but feeling decides what we find good.', wiki: 'David Hume' },
    rawls: { name: 'John Rawls', years: '1921–2002', looks: 'asks about justice', idea: 'A just order is one everyone could agree to without knowing where they themselves would end up in it.', wiki: 'John Rawls' },
  },

  alltag: [
    // ---------------- Money, work & shopping ----------------
    { id: 'a-wechselgeld', kind: 'alltag', icon: 'coin', title: 'Too much change',
      text: 'At the supermarket you pay with a €50 note. At home you notice you were given €20 too much in change. The shop is ten minutes away.',
      q: 'Do you take the money back?',
      opts: [{ t: 'Yes, today.', l: 'R' }, { t: 'Next time I shop there.', l: 'C' }, { t: 'No, a big chain will hardly notice.', l: 'F' }],
      why: { F: 'Who it actually hurts', R: 'It isn’t mine', C: 'I want to be someone who gives things like this back' },
      lenses: {
        F: 'If you look at the outcome, you ask: who is short of the 20? A big chain, hardly. Whether the person at the till gets into trouble, you don’t know. And honestly, “I’ll keep it” is often simply about your own advantage too. Plenty of people feel the same.',
        R: 'If you judge by principles, the case is simple: the money isn’t yours, so you give it back. Whether the shop is big or small, and whether anyone notices, changes nothing.',
        C: 'If you look at character, you ask: what kind of person do I want to be? An honest person gives the money back. Someone who also keeps a sense of proportion won’t necessarily make a special trip, but will sort it out on the next visit.' },
      fact: 'In Germany, for example, the law is clear: if you are paid too much by mistake, you have to give it back (unjust enrichment, § 812 of the German Civil Code).',
      twist: { text: 'Suppose it were a small bakery whose owner pays for every shortfall out of her own pocket.', q: 'Would you decide differently?',
        opts: ['Yes, then I’d definitely take it back', 'No, it makes no difference to me'],
        note: 'If you decide differently at the bakery than at the supermarket, you are paying attention to who bears the loss. That is a thought about outcomes. If you decide the same way, you are following a firm principle.' } },

    { id: 'a-stempeluhr', kind: 'alltag', icon: 'clock', title: 'The timesheet', pair: ['a-butter'],
      text: 'For weeks, your friendly colleague has been logging an hour more each day than he actually works. You know he has worries at home right now.',
      q: 'What do you do?',
      opts: [{ t: 'I talk to him in private.', l: 'C' }, { t: 'I tell the boss.', l: 'R' }, { t: 'Nothing, it’s none of my business.', l: 'F' }],
      why: { F: 'What helps him and the company most in the end', R: 'It isn’t fair on everyone else', C: 'What a good colleague would do' },
      lenses: {
        F: 'If you look at the outcome, you weigh it up: the damage to the company is fairly small, and the money may help him a lot right now. But if it comes out, he could lose far more than an hour a day. Keeping quiet has consequences too.',
        R: 'If you judge by principles, you see that everyone else logs their hours honestly. Rules that only apply to some people are unfair. His worries don’t make false records right.',
        C: 'If you look at character, you look for a way to be honest and considerate at once. A private conversation takes him seriously without exposing him, and gives him the chance to put it right himself.' },
      fact: 'In Germany, deliberately falsifying your working hours can justify dismissal without notice, often even without a prior warning (Federal Labour Court, 2011). A quiet word could save him from something much worse.' },

    { id: 'a-butter', kind: 'alltag', icon: 'cart', title: 'The butter', pair: ['a-stempeluhr'],
      text: 'In the supermarket you see an elderly woman slip a pack of butter into her coat pocket. Her coat is worn, and all she has in her basket is a loaf of bread.',
      q: 'What do you do?',
      opts: [{ t: 'Nothing, it’s none of my business.', l: 'F' }, { t: 'I tell the staff.', l: 'R' }, { t: 'I quietly offer to pay for the butter.', l: 'C' }],
      why: { F: 'Who it harms and who it helps', R: 'The law applies to everyone', C: 'What a compassionate person would do' },
      lenses: {
        F: 'If you look at the outcome, you see that the loss to the shop is tiny and her need is probably great. If she were caught, the shame and the penalty would be far worse than one pack of butter. Seen that way, looking away may be the gentlest option.',
        R: 'If you judge by principles, theft is theft, even out of need and even on a small scale. Anyone who makes exceptions has to be able to say where they stop.',
        C: 'If you look at character, you look for help that shames no one. Quietly offering to pay doesn’t simply accept the theft, and it doesn’t leave her on her own either. It does take courage and tact.' } },

    // ---------------- Neighbours & out and about ----------------
    { id: 'a-kratzer', kind: 'alltag', icon: 'car', title: 'The scratch', pair: ['gyges'], wiki: 'Hit and run',
      text: 'Pulling out of a parking space on your street, you scrape your neighbour’s car. A small scratch, and nobody saw it.',
      q: 'What do you do?',
      opts: [{ t: 'I ring his doorbell right away.', l: 'R' }, { t: 'I leave a note with my number.', l: 'C' }, { t: 'Nothing, it’s only a scratch.', l: 'F' }],
      why: { F: 'How much damage there really is', R: 'If you damage something, you own up', C: 'I want to be able to look my neighbour in the eye' },
      lenses: {
        F: 'If you look at the outcome, you ask what owning up achieves: trouble and costs for a scratch he may never notice. But if he does notice, he might suspect someone else. And honestly, keeping quiet is often about your own advantage too.',
        R: 'If you judge by principles, whoever causes damage answers for it. That nobody saw it doesn’t change what happened.',
        C: 'If you look at character, you think of the two of you: you see each other every day. A note shows responsibility without a fuss; ringing the bell is more personal. Either way you can still look him in the eye.' },
      fact: 'In Germany, a note on the windscreen is usually not enough. After an accident you must wait a reasonable time before driving off, and then report the damage to the owner or the police without delay. Otherwise you can be prosecuted for leaving the scene of an accident (§ 142 of the Criminal Code), even for minor damage.',
      twist: { text: 'Suppose it were a stranger’s car, in a town you’ll never visit again.', q: 'Would you act differently?',
        opts: ['No, I’d report it just the same', 'Honestly: probably yes'],
        note: 'If you would act differently with a stranger, you notice that part of our honesty depends on meeting again. Plato made exactly this question famous with the Ring of Gyges: how decent would we be if no one could see us?' } },

    { id: 'a-wlan', kind: 'alltag', icon: 'wifi', title: 'The open Wi-Fi',
      text: 'You have just moved in, and your internet won’t be connected for another three weeks. Your neighbour’s Wi-Fi has no password and the signal is strong in your flat.',
      q: 'Do you use it?',
      opts: [{ t: 'Yes, he won’t notice.', l: 'F' }, { t: 'I ask him whether that’s all right.', l: 'C' }, { t: 'No, it isn’t my connection.', l: 'R' }],
      why: { F: 'Whether it harms anyone', R: 'I don’t use what isn’t mine without asking', C: 'How a good neighbour behaves' },
      lenses: {
        F: 'If you look at the outcome, you ask: does he lose anything? Hardly, as long as you only browse a little. If you download a lot, his connection slows down. And whatever happens over his connection is traced back to him first.',
        R: 'If you judge by principles, the question isn’t whether he notices but whose connection it is. An open door doesn’t mean you may walk in.',
        C: 'If you look at character, the question is rather: how do I want to start out with my new neighbour? Asking turns something secret into something open, and the answer is often a friendly yes.' } },

    { id: 'a-sitzplatz', kind: 'alltag', icon: 'seat', title: 'The reserved seat',
      text: 'After a long day you board the train, with four hours ahead of you. In your reserved seat sits a man about your age, without a reservation, eyes closed. The train is full.',
      q: 'What do you do?',
      opts: [{ t: 'I wake him and ask for my seat.', l: 'R' }, { t: 'I suggest we take turns for the journey.', l: 'C' }, { t: 'I let him sleep, maybe he needs it more.', l: 'F' }],
      why: { F: 'Who needs the seat more right now', R: 'I paid for it, the seat is mine', C: 'Staying kind without making myself small' },
      lenses: {
        F: 'If you look at the outcome, you ask: who benefits more from the seat? Maybe he is ill or has been travelling for hours. Then again, maybe you are the more exhausted one. That is hard to tell from the outside, and whoever always gives way ends up carrying the burden alone.',
        R: 'If you judge by principles, it is clear: you reserved and paid, the seat is yours. Waking him politely isn’t wrong, it is simply your right.',
        C: 'If you look at character, you look for the right measure between kindness and self-respect. Taking turns takes him seriously, and yourself too. Generosity doesn’t mean always giving everything away; it means giving the right thing at the right time.' } },

    // ---------------- School & online ----------------
    { id: 'a-pruefung', kind: 'alltag', icon: 'doc', title: 'The exam questions', pair: ['a-hausarbeit'],
      text: 'The evening before your final exam, someone posts a photo in your class group chat, supposedly of the real questions.',
      q: 'Do you look at it?',
      opts: [{ t: 'No, I don’t open it.', l: 'R' }, { t: 'I let the school know.', l: 'C' }, { t: 'I take a look, everyone else is.', l: 'F' }],
      why: { F: 'That it ends up fair for everyone', R: 'Cheating isn’t allowed', C: 'I want to have really earned my result' },
      lenses: {
        F: 'If you look at the outcome, you think about the consequences: if everyone else looks and you don’t, you are at a disadvantage. If the school finds out, the exam may be reset. It only becomes fair when nobody has a head start, and sometimes that takes someone who speaks up.',
        R: 'If you judge by principles, cheating is cheating, even if everyone does it. A rule doesn’t count for less just because many people break it.',
        C: 'If you look at character, you think of yourself: a result you have earned feels different. Speaking up takes courage, because it can make you unpopular. And the photo may be a fake anyway.' } },

    { id: 'a-hausarbeit', kind: 'alltag', icon: 'spark', title: 'The essay', pair: ['a-pruefung'],
      text: 'An AI could write your essay in ten minutes, and quite well too. Your course rules say nothing about it: it isn’t explicitly allowed, but it isn’t forbidden either.',
      q: 'How do you go about it?',
      opts: [{ t: 'I let the AI write it and then revise the text.', l: 'F' }, { t: 'I ask what is allowed and say openly how I use the AI.', l: 'R' }, { t: 'I write it myself and use the AI for questions at most.', l: 'C' }],
      why: { F: 'What comes out of it in the end', R: 'Being honest about what is mine', C: 'I want to be able to do it myself' },
      lenses: {
        F: 'If you look at the outcome, you ask what the essay is for: a good mark and, if it goes well, what you learn along the way. A polished text you learned almost nothing from won’t help you much in the next exam.',
        R: 'If you judge by principles, it is about honesty: handing in a piece of work says that it is yours. Where the rules are silent, asking and disclosing openly is the safe way.',
        C: 'If you look at character, you ask: what do I want to be able to do when the course is over? Writing it yourself is hard work, but that is how you learn to think and to write. Used as a sparring partner, the AI can help without doing your thinking for you.' },
      fact: 'For essays and theses you usually sign a statement that you wrote the work yourself and listed every aid you used. Many schools and universities now have their own rules on AI. It’s worth asking.' },

    { id: 'a-foto', kind: 'alltag', icon: 'chat', title: 'The photo in the group chat', hint: 'Topic: being shamed online', wiki: 'Cyberbullying',
      text: 'In your class group chat, someone shares an embarrassing photo of a classmate. Lots of people reply with laughing messages.',
      q: 'What do you do?',
      opts: [{ t: 'I write in the group: “Delete that.”', l: 'R' }, { t: 'I message her privately that I’m on her side.', l: 'C' }, { t: 'I stay out of it.', l: 'F' }],
      why: { F: 'What helps her most', R: 'Nobody has the right to share a photo like that', C: 'I don’t want to just go along with it' },
      lenses: {
        F: 'If you look at the outcome, you ask: what actually helps her? A “Delete that” can make the photo disappear faster and give others courage. But it can also make you a target. Staying out of it mainly protects yourself. That is human, but it doesn’t help her.',
        R: 'If you judge by principles, nobody should be humiliated like this. Laughing along is taking part. Speaking up defends a rule that protects you too.',
        C: 'If you look at character, it is about compassion and courage. A private message tells her: you are not alone. It is quieter than objecting in the group, but it can mean a lot to her. And you can do both.' },
      fact: 'In Germany, you generally may only share pictures of other people with their consent (the right to one’s own image). Passing on images that could seriously damage someone’s reputation can even be a criminal offence (§ 201a of the Criminal Code).',
      help: 'If something like this happens to you, or something is weighing on you, talk to someone you trust. Many countries have free, confidential helplines for children and young people.',
      twist: { text: 'Suppose your best friend had shared the photo.', q: 'Would you act differently?',
        opts: ['No, I’d tell her to delete it just the same', 'I’d talk to her on her own first', 'Yes, I’d probably stay out of it'],
        note: 'Being quieter with a friend isn’t necessarily inconsistent: a word in private may achieve more with her than objecting in front of everyone. What matters is whether the photo disappears in the end.' } },

    { id: 'a-sterne', kind: 'alltag', icon: 'star', title: 'Five stars for a friend', pair: ['a-geschenk'],
      text: 'A friend has opened a café, and the first online reviews are bad. He asks you for a five-star review. You have never been there.',
      q: 'Do you write the review?',
      opts: [{ t: 'Yes, a few stars won’t hurt anyone.', l: 'F' }, { t: 'I go first, then review honestly.', l: 'C' }, { t: 'No, that misleads strangers.', l: 'R' }],
      why: { F: 'How much it helps him', R: 'Other people rely on honest reviews', C: 'What a good friend would do' },
      lenses: {
        F: 'If you look at the outcome, a good review may help your friend a lot. But the harm isn’t zero. Anyone who trusts the stars and is disappointed has lost time and money. And if everyone did it, soon nobody would believe a review.',
        R: 'If you judge by principles, a review without a visit is a deception, however kindly meant. The people who read it have done nothing to you.',
        C: 'If you look at character, you want to be helpful and honest at once. Going, trying it and then writing honestly is more effort. In return, your opinion really helps him, including to get better.' },
      fact: 'Since May 2022, German law explicitly bans businesses from posting fake customer reviews or commissioning them (Act against Unfair Competition, Annex No. 23c, based on an EU directive). A favour review at the owner’s request can fall under this.' },

    // ---------------- Friends & family ----------------
    { id: 'a-geschenk', kind: 'alltag', icon: 'gift', title: 'The present', pair: ['luege', 'a-sterne'],
      text: 'Your aunt spent weeks knitting you a jumper. You don’t like it at all. Beaming, she asks: “Well? Do you like it?”',
      q: 'What do you say?',
      opts: [{ t: '“Yes, I love it!”', l: 'F' }, { t: 'I honestly praise all the work.', l: 'C' }, { t: 'Honest and kind: it’s not quite my style.', l: 'R' }],
      why: { F: 'That she is happy', R: 'I don’t want to lie, not even about small things', C: 'What a loving person would say' },
      lenses: {
        F: 'If you look at the outcome, “Yes, I love it!” makes her happy and costs nobody anything. There is one catch: she might knit you another one next year.',
        R: 'If you judge by principles, a small lie is still a lie. Saying honestly and kindly that it isn’t quite your style trusts her to handle the truth.',
        C: 'If you look at character, you look for a tactful way that doesn’t involve lying: you praise what truly deserves praise, the time, the effort, the affection. That is true, and it still makes her happy.' } },

    { id: 'a-konzert', kind: 'alltag', icon: 'music', title: 'The concert', pair: ['p-versprechen'],
      text: 'You promised a friend you would help her move house on Saturday, and it will go on late into the night. On Saturday morning you are unexpectedly offered a ticket to your favourite band’s sold-out concert, tonight.',
      q: 'What do you do?',
      opts: [{ t: 'I help, as promised.', l: 'R' }, { t: 'I ask her honestly whether she can manage without me.', l: 'C' }, { t: 'I go and send someone in my place.', l: 'F' }],
      why: { F: 'Whether the move works out without me', R: 'A promise is a promise', C: 'What kind of friend I want to be' },
      lenses: {
        F: 'If you look at the outcome, you ask: will the move work out without me? With a good replacement, perhaps it will, and you get to experience something that won’t come round again. But her trust in your word is an outcome that counts as well.',
        R: 'If you judge by principles, a promise is a promise. A promise that only holds until something better comes along isn’t one. Only she can release you.',
        C: 'If you look at character, you want to be open rather than sneaky. Asking honestly lets her have a say, and then you have to be able to accept a no.' },
      twist: { text: 'Suppose she already had five other helpers.', q: 'Does that change anything for you?',
        opts: ['No, a promise is a promise', 'Yes, then I hardly matter'],
        note: 'If you now decide differently, you are looking at the outcome: with five helpers, less depends on you. If you stick with your answer, you are treating the promise as something that holds regardless.' } },

    { id: 'a-erbe', kind: 'alltag', icon: 'users', title: 'The unequal inheritance', pair: ['p-familie'],
      text: 'Your grandmother leaves you 20,000 and your brother only 2,000. She felt he never looked after her. He is deeply hurt.',
      q: 'Do you share with him?',
      opts: [{ t: 'No, it was her last wish.', l: 'R' }, { t: 'Yes, fifty-fifty, to keep the peace.', l: 'F' }, { t: 'I give him some and talk to him.', l: 'C' }],
      why: { F: 'That the family sticks together', R: 'Her last wish stands', C: 'What a good sister or brother would do' },
      lenses: {
        F: 'If you look at the outcome, you ask what weighs more in the end: the money or your relationship with your brother. A fight over an inheritance can divide a family for years. Fifty-fifty costs you money, but can buy a lot of peace.',
        R: 'If you judge by principles, you respect her wishes: she had her reasons, and it was her money. Redistributing everything overrides her final decision.',
        C: 'If you look at character, you look for the right measure: generous to your brother without brushing her wishes aside completely. An honest conversation about why she decided as she did can heal more than any sum.' } },

    { id: 'a-gesehen', kind: 'alltag', icon: 'eye', title: 'What you saw', care: 'infidelity', pair: ['a-diagnose'],
      text: 'In a café you see your best friend’s girlfriend kissing another man. She hasn’t noticed you.',
      q: 'Do you tell your friend?',
      opts: [{ t: 'Yes, I’ll tell him soon.', l: 'R' }, { t: 'I talk to her first.', l: 'C' }, { t: 'No, I stay out of it.', l: 'F' }],
      why: { F: 'What hurts least in the end', R: 'He has a right to know', C: 'What a good friend would do' },
      calm: 'There is no wrong answer here. All three paths can come from caring.',
      lenses: {
        F: 'If you look at the outcome, you ask what the truth will do. Maybe it wasn’t what it looked like. Maybe something breaks that would otherwise have lasted. But a secret can hurt too, if it comes out later and he learns that you knew.',
        R: 'If you judge by principles, your friend has a right to the truth about his own life. Keeping quiet means deciding over his head what he is allowed to know.',
        C: 'If you look at character, you want to be loyal to him and fair to her. Talking to her first gives her the chance to tell him herself, and you still stay honest.' },
      twist: { text: 'Suppose you weren’t sure what you had seen.', q: 'Would you still tell him?',
        opts: ['Yes, he should decide for himself', 'No, not without being sure'],
        note: 'Uncertainty shifts the question: now it is no longer only about his right to the truth, but also about not spreading a false suspicion.' } },

    { id: 'a-diagnose', kind: 'alltag', icon: 'heart', title: 'The diagnosis', care: 'serious illness', pair: ['a-gesehen'],
      text: 'Your father is seriously ill. He has told his doctors he doesn’t want to know how things stand. Your sister thinks he must be told, so that he can still put his affairs in order.',
      q: 'Who do you side with?',
      opts: [{ t: 'His wish stands, we say nothing.', l: 'R' }, { t: 'We gently ask him whether he still feels that way.', l: 'C' }, { t: 'He should be told.', l: 'F' }],
      why: { F: 'What makes the time he has left easiest for him', R: 'It is his decision alone', C: 'What a loving child would do' },
      calm: 'There is no wrong answer here. All three come from love.',
      lenses: {
        F: 'If you look at the outcome, you ask what helps him more: the calm of not knowing, or the chance to put things in order and say goodbye. There is no general answer to that, only his.',
        R: 'If you judge by principles, it is his life and his decision. Telling him against his express wish takes that decision away from him.',
        C: 'If you look at character, you look for a way to be caring without deciding for him. A gentle conversation about whether he still feels the same leaves the choice with him and takes your sister’s worry seriously.' },
      fact: 'Many legal systems recognise a right not to know. In Germany, for example, doctors do not have to inform a patient who has expressly waived it (§§ 630c and 630e of the Civil Code).' },
  ],

  philo: [
    // ---------------- Doing right ----------------
    { id: 'p-absicht', kind: 'philo', icon: 'scale', title: 'Intention or outcome',
      text: 'A man donates a lot of money just to look good in the newspaper, and helps many people with it. A woman means to help her neighbour, but by accident makes everything worse.',
      q: 'What counts more in an action?',
      opts: ['The outcome', 'The intention', 'Both together', 'What it reveals about the person'],
      voices: [
        { who: 'kant', fit: [1], says: 'The intention counts, or more precisely the will to do what is right because it is right. A good will is the only thing that is good without qualification, even if it achieves nothing. The vain donor does what is right, but his action has no moral worth.',
          read: 'Groundwork of the Metaphysics of Morals (1785), Section I' },
        { who: 'mill', fit: [0, 3], says: 'Whether an action is right depends on what it brings about. Someone who saves a drowning person does the right thing, whatever the reason. The motive, though, says a lot about whether someone is a good person.',
          read: 'Utilitarianism (1861), Chapter 2',
          dispute: 'Mill draws a fine line between what you intend to do (which counts for the act) and the motive behind it (which only counts for judging the person). Whether actual or foreseeable consequences count when outcomes are unpredictable is still debated among utilitarians.' },
        { who: 'aristoteles', fit: [2, 3], says: 'The two belong together. To act well is to do the right thing knowingly, by choice and from a settled good character. Someone who causes harm out of ignorance acts involuntarily and deserves leniency.',
          read: 'Nicomachean Ethics, Book II, Chapter 4; Book III, Chapter 1' },
        { who: 'nietzsche', fit: [], says: 'He regards a morality that measures everything by intention as the prejudice of a particular era. For him, conscious intention is only the surface of an action; what really matters lies in what we do not intend.',
          read: 'Beyond Good and Evil (1886), § 32' },
      ] },

    { id: 'p-versprechen', kind: 'philo', icon: 'key', title: 'The old promise', pair: ['a-konzert'],
      text: 'Three years ago you promised a friend you would be her maid of honour or best man. Since then you have drifted apart. Now the date is set.',
      q: 'Do you have to keep your promise, even though things have changed?',
      opts: ['Yes, a promise is a promise', 'Yes, unless it costs me too much', 'I talk to her and ask her to release me', 'No, things are different now'],
      voices: [
        { who: 'kant', fit: [0, 2], says: 'Yes. A promise that only holds while it is convenient is no promise at all. That you feel differently today does not cancel your word. Only she can release you.',
          read: 'Groundwork of the Metaphysics of Morals (1785), the example of the false promise',
          dispute: 'Kant’s famous example is about a promise you already intend to break when you make it. Applying it to a promise made honestly that later becomes a burden is common, but it is an extension.' },
        { who: 'mill', fit: [0, 1], says: 'Usually yes. Being able to rely on each other’s word is one of the most important goods in a society, and he counts breaking faith as an injustice. You may break a promise only if keeping it would do clearly more harm. An awkward day is not that.',
          read: 'Utilitarianism (1861), Chapter 5' },
        { who: 'aristoteles', fit: [2], says: 'If friends have truly changed, a friendship may end. But something is still owed to the friendship that was. The wise course is to talk, rather than break off in silence or suffer in silence.',
          read: 'Nicomachean Ethics, Book IX, Chapter 3; on equity, which softens rigid rules in particular cases: Book V, Chapter 10' },
        { who: 'nietzsche', fit: [0], says: 'Surprisingly, being entitled to make promises is, for him, the mark of the strong, sovereign person who keeps their word even against chance. But he keeps it out of pride, not out of duty. That is his own route to the same answer.',
          read: 'On the Genealogy of Morality (1887), Second Essay, Sections 1 and 2' },
        { who: 'arendt', fit: [0, 2], says: 'What people do is unpredictable. Promises are the remedy: small fixed points that others can build on. Breaking them lightly takes that footing away from others.',
          read: 'The Human Condition (1958), section on promising' },
      ] },

    { id: 'p-strafe', kind: 'philo', icon: 'flag', title: 'The old crime',
      text: 'Many years ago a man committed a large fraud. Since then he has lived decently, and no one is in danger any more. Now the crime comes to light. Whether it would legally be time-barred doesn’t matter here: this is about morality.',
      q: 'Should he still be punished?',
      opts: ['Yes, wrongdoing demands punishment', 'Only if it prevents future harm', 'He should make good the damage', 'Forgiveness is stronger'],
      voices: [
        { who: 'kant', fit: [0], says: 'Yes. Punishment is just because a wrong was done, not because it achieves something. Punishing someone only to deter others would be using him merely as a means.',
          read: 'The Metaphysics of Morals, Doctrine of Right (1797), General Remark E after § 49' },
        { who: 'mill', fit: [1, 2], says: 'Punishment is itself an evil. It is justified only if it prevents future harm, here mainly by deterring others. If that benefit is small, there is little case for a harsh penalty.',
          read: 'Utilitarianism (1861), Chapter 5',
          dispute: 'Mill has no fully worked-out theory of punishment of his own. This follows his utilitarianism in general; Jeremy Bentham set it out in more detail.' },
        { who: 'aristoteles', fit: [2], says: 'Whoever has gained an advantage at others’ expense should have it taken away, so that the balance is restored. Punishment is also a kind of cure, meant to improve. For a man who reformed long ago, what remains is chiefly the restoring of balance.',
          read: 'Nicomachean Ethics, Book V, Chapter 4; Book II, Chapter 3',
          dispute: 'His “corrective justice” is mainly about settling things between citizens. Turning it into a full theory of punishment is an interpretation.' },
        { who: 'nietzsche', fit: [3], says: 'Over the course of history punishment has had many shifting meanings; its root lies in the old relationship between creditor and debtor. The stronger a community is, the more it can afford not to punish. He sees mercy as the privilege of the most powerful.',
          read: 'On the Genealogy of Morality (1887), Second Essay, Sections 4 to 13, especially 10' },
      ] },

    { id: 'p-gefuehl', kind: 'philo', icon: 'axis', title: 'Head or heart',
      text: 'A man in the street asks you for money; he looks desperate. Your gut says: give him something. Your head says: this could be a well-known scam.',
      q: 'What should you listen to on moral questions?',
      opts: ['My head', 'My gut', 'Both should agree', 'The head only explains what the gut already wants'],
      voices: [
        { who: 'kant', fit: [0], says: 'Reason. Inclinations and feelings are not moral reasons. Still, reason itself produces a special feeling: respect for the moral law.',
          read: 'Groundwork of the Metaphysics of Morals (1785), Section I, the footnote on respect' },
        { who: 'mill', fit: [0, 2], says: 'Both have their place. After his own mental crisis he wrote that cultivating the feelings, through poetry for example, matters as much as cultivating the intellect. But for him, what is right is settled by thinking about consequences.',
          read: 'Autobiography (1873), Chapter 5' },
        { who: 'aristoteles', fit: [2], says: 'Virtue means that feeling and reasoned judgement agree. A good person does the right thing gladly, not against inner resistance.',
          read: 'Nicomachean Ethics, Book II, Chapter 3; Book VI, Chapter 13' },
        { who: 'nietzsche', fit: [1, 3], says: 'The body and its feelings deserve more trust than philosophers have given them. Conscious thought is, for him, only a small tool of the body’s much greater wisdom.',
          read: 'Thus Spoke Zarathustra, Part I, “On the Despisers of the Body”' },
        { who: 'hume', fit: [3], says: 'Reason alone moves us to nothing. It only shows the way; the goals are set by the passions. Even what we call good or bad rests on feelings of approval and disapproval.',
          read: 'A Treatise of Human Nature (1739–40), Book II, Part 3, Section 3; Book III, Part 1, Section 1',
          dispute: 'Some count Hume among the character-based ethicists. Matching him to the last answer here concerns above all his account of how reason and feeling relate.' },
      ] },

    // ---------------- Me and others ----------------
    { id: 'p-familie', kind: 'philo', icon: 'users', title: 'Nephew or strangers', pair: ['tg:liebe', 'a-erbe', 'teich'],
      text: 'You can give 500: towards your nephew’s braces, which his health insurance won’t cover, or to a charity that would help far more people with it.',
      q: 'May you put your family first?',
      opts: ['Yes, family comes first', 'No, the charity helps more', 'Family, but not at any price', 'It depends on how great the need is'],
      voices: [
        { who: 'kant', fit: [0, 2], says: 'In benevolence you may give more to those closer to you. Favouring them is allowed, as long as you don’t withhold from anyone what you owe them. Doing wrong for the sake of family is never allowed.',
          read: 'The Metaphysics of Morals, Doctrine of Virtue (1797), § 28' },
        { who: 'mill', fit: [1, 3], says: 'In principle everyone counts equally, as for an impartial spectator. At the same time, most good deeds in everyday life are aimed at particular people, and that is fine. But if the money helps far more elsewhere, there is a strong case for the charity.',
          read: 'Utilitarianism (1861), Chapter 2',
          dispute: 'How much priority for those close to us Mill would allow is an open question among scholars.' },
        { who: 'aristoteles', fit: [0, 2], says: 'We owe different things to parents, siblings, friends and fellow citizens. This gradation is not unjust; it is part of a good life.',
          read: 'Nicomachean Ethics, Book VIII, Chapters 9 to 12; Book IX, Chapter 2' },
        { who: 'nietzsche', fit: [], says: 'He distrusted love of one’s neighbour as a flight from oneself, and set against it love of the farthest, of what a person can become. In any case, he did not see the equality of all as an ideal.',
          read: 'Thus Spoke Zarathustra, Part I, “On Love of the Neighbour”',
          dispute: 'Nietzsche says nothing directly about this question. This is an extension of his thought.' },
        { who: 'konfuzius', fit: [0, 2], says: 'Humaneness is rooted in respect for parents and siblings and widens outward from there. Whoever neglects those closest to them lacks the foundation.',
          read: 'Analects (Lunyu) 1.6 and 13.18; the well-known line about the root of humaneness (1.2) comes from his disciple You',
          dispute: 'The explicit doctrine of graded love comes rather from his successor Mencius. It is present in Confucius, but not worked out in that form.' },
      ] },

    { id: 'p-mitleid', kind: 'philo', icon: 'chat', title: 'The evening calls',
      text: 'For months an acquaintance has been ringing you almost every evening to talk about her troubles. You suffer along with her every time, and after the calls you often feel low yourself.',
      q: 'Is your compassion a good thing here?',
      opts: ['Yes, it makes us human', 'Only if it leads to action', 'In the right measure', 'No, it drags you both down'],
      voices: [
        { who: 'kant', fit: [1], says: 'Compassion alone is no moral reason. Helping only out of sympathy is kind, but not done from duty. Even so, we should cultivate sympathetic feelings, because they help us do what is right.',
          read: 'Groundwork of the Metaphysics of Morals (1785), Section I; Doctrine of Virtue (1797), §§ 34 and 35',
          dispute: 'Kant is often seen as cold. The passage in the Doctrine of Virtue shows that he gives feelings more room than his reputation suggests.' },
        { who: 'mill', fit: [0, 1], says: 'Sympathy is one root of our sense of justice and should grow with education. What matters, though, is whether it actually relieves suffering.',
          read: 'Utilitarianism (1861), Chapters 3 and 5' },
        { who: 'aristoteles', fit: [2], says: 'Pity is a natural feeling. You can feel it too strongly or too weakly. It is good at the right time, towards the right people and in the right measure.',
          read: 'Nicomachean Ethics, Book II, Chapter 6; Rhetoric, Book II, Chapter 8',
          dispute: 'For Aristotle, pity is not a virtue of its own but one of many feelings to which the right measure applies.' },
        { who: 'nietzsche', fit: [3], says: 'Pity multiplies suffering in the world and makes both sides weaker. It would be better to help the other person become strong.',
          read: 'The Antichrist (1888), § 7' },
        { who: 'schopenhauer', fit: [0], says: 'Compassion is the only true foundation of morality. Only someone who feels another’s suffering as if it were their own truly acts well.',
          read: 'On the Basis of Morality (1840)' },
      ] },

    { id: 'p-neid', kind: 'philo', icon: 'self', title: 'The good news',
      text: 'Your best friend gets the scholarship you both applied for. She deserved it, and you know it. You congratulate her sincerely, and yet something gnaws at you: envy.',
      q: 'Is envy always bad?',
      opts: ['Yes, envy is poison', 'The feeling is normal, what counts is what I do with it', 'It can spur me on', 'Sometimes it shows that something is unfair'],
      voices: [
        { who: 'kant', fit: [0, 1], says: 'He counts envy among the vices directed against other people: seeing others’ well-being with pain, even though it takes nothing from you. The tendency is part of human nature. It becomes truly bad when you nurture it or act on it.',
          read: 'The Metaphysics of Morals, Doctrine of Virtue (1797), § 36' },
        { who: 'mill', fit: [0, 1], says: 'He considers envy one of the most anti-social of passions: it makes the envious person unhappy and turns against the happiness of others. But a feeling on its own is not yet an action. What would count for him is what you make of it.',
          read: 'On Liberty (1859), Chapter 4' },
        { who: 'aristoteles', fit: [2], says: 'He distinguishes two feelings. Envy is pain that someone else has something good, and would rather take it from them. Emulation is pain that you don’t have it yourself, and drives you to earn it. The first is bad, the second good.',
          read: 'Rhetoric, Book II, Chapters 10 and 11; Nicomachean Ethics, Book II, Chapter 7' },
        { who: 'nietzsche', fit: [2], says: 'He sees two faces. The ancient Greeks, he says, valued the envy that spurs on to competition and makes you better. It turns dangerous when it becomes secret resentment that wants to cut the other down instead of growing yourself.',
          read: '“Homer’s Contest” (1872); On the Genealogy of Morality (1887), First Essay, Section 10',
          dispute: 'Nietzsche describes resentment (ressentiment) mainly as the attitude of whole groups. Applying it to one person’s envy is an interpretation.' },
        { who: 'rawls', fit: [1], says: 'He separates envy from justified resentment: resentment is a response to injustice, while envy begrudges others something even when they came by it fairly. If your friend won fairly, your feeling is human, but it gives you no claim. A just society, though, should not allow inequalities so great that they wound people’s self-respect.',
          read: 'A Theory of Justice (1971), §§ 80 and 81' },
      ] },

    { id: 'p-tiere', kind: 'philo', icon: 'paw', title: 'In the chilled aisle',
      text: 'You are standing in the chilled aisle of the supermarket: a cheap chicken from intensive farming, an expensive free-range one, and next to them a pea-based substitute.',
      q: 'Is it all right to eat animals?',
      opts: ['Yes, without a second thought', 'Yes, if the animals lived well and didn’t suffer', 'Less, and more mindfully', 'No, not if I can eat well without it'],
      voices: [
        { who: 'kant', fit: [1], says: 'For him, we have duties only towards rational beings. Even so, cruelty to animals is wrong, because it dulls the compassion we need in dealing with people. Killing animals quickly and without torment he considered permissible.',
          read: 'The Metaphysics of Morals, Doctrine of Virtue (1797), § 17',
          dispute: 'Whether this indirect reasoning is enough is still debated. Some Kant scholars argue that his approach implies more protection for animals than he himself saw.' },
        { who: 'mill', fit: [1, 2], says: 'For him, happiness and suffering count not only for humans but, as far as possible, for all sentient beings. Making animals suffer needlessly therefore does real harm. Whether we may eat animals then depends mainly on how they lived and died.',
          read: 'Utilitarianism (1861), Chapter 2',
          dispute: 'Mill did not explicitly address eating meat. This follows from his principle.' },
        { who: 'aristoteles', fit: [0], says: 'He saw nature as a hierarchy: plants exist for animals, animals for humans. Using and eating animals went without saying for him.',
          read: 'Politics, Book I, Chapter 8',
          dispute: 'How literally the passage is meant is disputed. Virtue ethicists today tend to ask whether indifference to suffering fits a good character.' },
        { who: 'nietzsche', fit: [], says: 'Your reasons would come first: a morality resting mainly on pity made him suspicious. Whether you eat meat would probably matter less to him than whether your stance is truly your own or merely taken over.',
          read: 'On the Genealogy of Morality (1887), Preface, Section 5',
          dispute: 'Nietzsche hardly addressed animals as a moral question. This is an extension of his thought.' },
        { who: 'singer', fit: [3], says: 'If a being can suffer, its suffering counts, whether human or animal. Giving animals less consideration simply because they belong to another species is what he calls speciesism. Factory farming causes great suffering for a small pleasure, so we should do without it wherever we can.',
          read: 'Animal Liberation (1975)' },
      ] },

    // ---------------- My life ----------------
    { id: 'p-selbstschaden', kind: 'philo', icon: 'mountain', title: 'The rock face',
      text: 'A friend wants to climb a difficult rock face alone and without a rope. He knows the risk exactly, and nobody depends on him.',
      q: 'May he do it, and may others stop him?',
      opts: ['Yes, that is his business alone', 'Yes, but others may warn him strongly', 'No, we also have duties to ourselves', 'A daring life is worth more'],
      voices: [
        { who: 'kant', fit: [2], says: 'There are duties to oneself. Risking your life for a mere thrill treats yourself merely as a means to a pleasure. But others could not force him; such duties are for each person to fulfil.',
          read: 'The Metaphysics of Morals, Doctrine of Virtue (1797), §§ 5 to 8',
          dispute: 'Kant writes about self-mutilation and excess, not about dangerous sports. Applying it here is an interpretation.' },
        { who: 'mill', fit: [0, 1], says: 'Over himself, over his own body and mind, each person is sovereign. Others may warn, plead and persuade, but not compel. You may only hold back someone who doesn’t know the danger, like a person about to step onto an unsafe bridge.',
          read: 'On Liberty (1859), Chapters 1, 4 and 5' },
        { who: 'aristoteles', fit: [2], says: 'Courage is the mean between cowardice and rashness. Someone who faces great dangers without good reason is not brave but reckless. And humans are social beings: whoever endangers himself affects others too.',
          read: 'Nicomachean Ethics, Book II, Chapter 7; Book III, Chapters 6 to 9' },
        { who: 'nietzsche', fit: [3], says: 'A daring life of your own is worth more than safe mediocrity. He even explicitly urged people to live dangerously.',
          read: 'The Gay Science (1882), § 283 (where the actual phrase “live dangerously” appears)' },
        { who: 'beauvoir', fit: [1], says: 'Being free means willing your own choice and answering for it. But my freedom is bound up with the freedom of others. Whoever puts himself in danger should ask what he is loading onto the people who love him.',
          read: 'The Ethics of Ambiguity (1947)',
          dispute: 'She did not write about climbing. Applying her thought to this case is an interpretation.' },
      ] },

    { id: 'p-selbstliebe', kind: 'philo', icon: 'heart', title: 'Always saying yes',
      text: 'For years you have said yes to everything: overtime, favours, helping people move. By now you are tired. A friend says: “Think of yourself for once.”',
      q: 'How much self-love is good?',
      opts: ['Me first, then the others', 'I count as much as anyone else', 'Look after myself so I can be good to others', 'Thinking of yourself is selfish'],
      voices: [
        { who: 'kant', fit: [2], says: 'Looking after yourself is natural and permitted. Constantly subordinating yourself to others even violates the respect you owe yourself. Only, self-love must never be placed above the moral law.',
          read: 'The Metaphysics of Morals, Doctrine of Virtue (1797), §§ 11 and 12 (“On Servility”); Critique of Practical Reason (1788)' },
        { who: 'mill', fit: [1], says: 'Your happiness counts exactly as much as anyone else’s, no more and no less. A sacrifice that brings no one more happiness he considers wasted.',
          read: 'Utilitarianism (1861), Chapter 2' },
        { who: 'aristoteles', fit: [2], says: 'A good person should love himself, but in the right sense: cultivating the best in himself, rather than grabbing as much money and honour as he can.',
          read: 'Nicomachean Ethics, Book IX, Chapter 8' },
        { who: 'nietzsche', fit: [0], says: 'Healthy selfishness is, for him, a sign of strength. What he finds suspicious is rather the much-praised selflessness.',
          read: 'Thus Spoke Zarathustra, Part III, “On the Three Evils”' },
      ] },

    { id: 'p-gutesleben', kind: 'philo', icon: 'sun', title: 'Looking back at 80', pair: ['erlebnis'],
      text: 'Imagine you are 80 and looking back on your life. Not at a single day, but at the whole of it.',
      q: 'How would you know it had been a good life?',
      opts: ['I was happy', 'I lived decently', 'I developed my abilities', 'I would live it exactly the same way again'],
      voices: [
        { who: 'kant', fit: [1], says: 'Happiness is not the measure. A good life is one that is worthy of happiness, a life of doing right. That worthiness and happiness come together in the end is the highest good, something we can only hope for.',
          read: 'Critique of Practical Reason (1788), Part One, “Dialectic”' },
        { who: 'mill', fit: [0], says: 'A good life is a happy one. But happiness is more than pleasure: knowledge, friendship, art and sympathy are higher pleasures and count for more. His is the comparison that it is better to be Socrates dissatisfied than a fool satisfied.',
          read: 'Utilitarianism (1861), Chapter 2' },
        { who: 'aristoteles', fit: [2], says: 'A flourishing life means being active over a whole lifetime in line with your best abilities and virtues, with friends and enough to live on.',
          read: 'Nicomachean Ethics, Book I, Chapter 7; Book X, Chapters 6 to 8' },
        { who: 'nietzsche', fit: [3], says: 'Become who you are. And he proposes a test: could you want to live this life again, exactly the same, countless times, with all its pain and all its joy?',
          read: 'The Gay Science (1882), §§ 270 and 341' },
        { who: 'epikur', fit: [0], says: 'Happiness is calm joy: no pain in the body, no turmoil in the soul. For that you need little, above all friends, insight and no fear of death.',
          read: 'Letter to Menoeceus' },
      ] },

    { id: 'p-freierwille', kind: 'philo', icon: 'loop', title: 'Everything has causes', pair: ['laplace'],
      text: 'Suppose everything you do has causes: your genes, your upbringing, your brain. A woman has stolen from a shop.',
      q: 'Is she still responsible?',
      opts: ['Only if she was truly free', 'Yes, if she acted without coercion', 'No, without free will there is no guilt', 'Guilt was invented in order to punish'],
      voices: [
        { who: 'kant', fit: [0], says: 'Anyone who makes moral judgements must presuppose freedom. We don’t find it in the world of causes, but as acting beings we have to think of ourselves as free.',
          read: 'Groundwork of the Metaphysics of Morals (1785), Section III; Critique of Practical Reason (1788)',
          dispute: 'How Kant reconciles freedom with the laws of nature is one of the hardest questions in Kant scholarship.' },
        { who: 'mill', fit: [1], says: 'Even if everything has causes, we are responsible. Precisely because people respond to praise, blame and reasons, responsibility makes sense.',
          read: 'A System of Logic (1843), Book VI, Chapter 2' },
        { who: 'aristoteles', fit: [1], says: 'You are responsible if you act voluntarily: on your own initiative and knowing the circumstances. We are even partly responsible for our own character, because we shaped it through what we did.',
          read: 'Nicomachean Ethics, Book III, Chapters 1 to 5',
          dispute: 'Aristotle does not ask the modern question of whether everything is predetermined. Matching him here is an extension.' },
        { who: 'nietzsche', fit: [3], says: 'The doctrine of free will was invented so that people could be found guilty and punished. But he considers the “unfree will” just as much a myth: for him there are only strong and weak wills.',
          read: 'Twilight of the Idols (1889), “The Four Great Errors”, § 7; Beyond Good and Evil (1886), § 21' },
      ],
      stats: { txt: 'In the 2020 PhilPapers Survey, about 59 percent of the philosophers asked held that causes and responsibility are compatible, about 19 percent believed in free will in a strong sense, and about 11 percent in no free will at all.',
        src: 'Bourget and Chalmers, Philosophers’ Imprint 2023' } },
  ],
};
